#include <cstddef>

class Arena
{
public:
    explicit Arena(std::size_t capacity) : m_capacity{ capacity } {}

    // Offset of a new piece of size bytes aligned to align, or -1 if it does not fit.
    long long allocate(std::size_t size, std::size_t align)
    {
        const std::size_t start{ (m_used + align - 1) & ~(align - 1) };   // round up to a multiple of align
        if (start > m_capacity || size > m_capacity - start) return -1;
        m_used = start + size;
        return static_cast<long long>(start);
    }

    std::size_t used() const { return m_used; }
    void reset() { m_used = 0; }

private:
    std::size_t m_capacity;
    std::size_t m_used{ 0 };
};

unitTests:
TEST("the example")
{
    Arena a{ 64 };
    CHECK_EQ(a.allocate(3, 1), 0ll);
    CHECK_EQ(a.allocate(4, 4), 4ll);
    CHECK_EQ(a.allocate(8, 8), 8ll);
    CHECK_EQ(a.used(), std::size_t{ 16 });
    CHECK_EQ(a.allocate(64, 1), -1ll);
    CHECK_EQ(a.used(), std::size_t{ 16 });
}
TEST("already aligned positions are not moved") { Arena a{ 32 }; CHECK_EQ(a.allocate(8, 8), 0ll); CHECK_EQ(a.allocate(8, 8), 8ll); }
TEST("sixteen-byte alignment") { Arena a{ 64 }; a.allocate(1, 1); CHECK_EQ(a.allocate(4, 16), 16ll); CHECK_EQ(a.used(), std::size_t{ 20 }); }
TEST("an exact fit") { Arena a{ 16 }; CHECK_EQ(a.allocate(16, 1), 0ll); CHECK_EQ(a.allocate(1, 1), -1ll); }
TEST("alignment padding can make it not fit") { Arena a{ 16 }; a.allocate(9, 1); CHECK_EQ(a.allocate(8, 8), -1ll); CHECK_EQ(a.used(), std::size_t{ 9 }); CHECK_EQ(a.allocate(7, 1), 9ll); }
TEST("reset starts again") { Arena a{ 8 }; a.allocate(8, 1); a.reset(); CHECK_EQ(a.used(), std::size_t{ 0 }); CHECK_EQ(a.allocate(8, 1), 0ll); }
TEST("zero-size pieces") { Arena a{ 8 }; CHECK_EQ(a.allocate(0, 1), 0ll); CHECK_EQ(a.used(), std::size_t{ 0 }); }

